<?php require 'config.php';$rows=[];if($_SERVER['REQUEST_METHOD']==='GET' && isset($_GET['origin'])){$sql='SELECT * FROM flights WHERE origin LIKE ? AND destination LIKE ? AND DATE(departure)=?';$s=$pdo->prepare($sql);$s->execute(['%'.$_GET['origin'].'%','%'.$_GET['destination'].'%',$_GET['date']]);$rows=$s->fetchAll();}?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"><title>Search flights</title></head><body><header><strong>SkyBook</strong><nav><a href="index.php">Home</a><a href="dashboard.php">Dashboard</a></nav></header><div class="wrap"><div class="card"><h1>Search flights</h1><form><label>From</label><input name="origin" placeholder="Chennai" required><label>To</label><input name="destination" placeholder="Delhi" required><label>Date</label><input type="date" name="date" required><button>Search</button></form></div><?php foreach($rows as $f):?><div class="card"><h2><?=h($f['airline'])?> · <?=h($f['flight_no'])?></h2><p><?=h($f['origin'])?> → <?=h($f['destination'])?> | <?=h($f['departure'])?> – <?=h($f['arrival'])?></p><p><?=h($f['travel_class'])?> · ₹<?=h($f['fare'])?> · <?=h($f['available_seats'])?> seats available</p><a class="btn" href="book.php?flight=<?=$f['id']?>">Book ticket</a></div><?php endforeach;?></div></body></html>